def transform_v4_fixed(grid):
    h, w = len(grid), len(grid[0])

    result = [[0]*w for _ in range(h)]

    for r in range(h):
        row = grid[r]
        non_positions = [(c, row[c]) for c in range(w) if row[c] != 0]

        if len(non_positions) == 0:
            continue

        pre_4_count = sum(1 for c, v in non_positions if c < 4)
        post_4_count = sum(1 for c, v in non_positions if c >= 4)

        if pre_4_count > 0 and post_4_count > 0:
            for i in range(len(non_positions)):
                result[r][min(4 + i, w - 1)] = non_positions[i][1]
        elif pre_4_count > 0 and post_4_count == 0:
            if len(non_positions) == 1:
